  "Embark on an orbital journey across the sacred geography of India. Traverse timeless monuments in photorealistic 360° AR/VR, interact with 3D living cultural traditions, and turn the pages of ancient digital manuscripts.": {
    hi: "भारत के पावन भूगोल की कक्षीय यात्रा पर निकलें। फोटोरियलिस्टिक 360° AR/VR में कालातीत स्मारकों का भ्रमण करें, 3D जीवंत सांस्कृतिक परंपराओं से जुड़ें और प्राचीन डिजिटल पांडुलिपियों के पन्ने पलटें।",
    mr: "भारताच्या पवित्र भूगोलाच्या कक्षीय प्रवासाला सुरुवात करा. छायाचित्रमय 360° AR/VR मध्ये स्मारकांचे दर्शन घ्या, 3D जिवंत सांस्कृतिक परंपरांशी संवाद साधा आणि प्राचीन हस्तलिखितांची पाने उलटा.",
    bn: "ভারতের পবিত্র ভূগোলে এক মহাজাগতিক যাত্রা শুরু করুন। ফটোরিয়ালিস্টিক 360° AR/VR-এ কালজয়ী স্মৃতিস্তম্ভ পরিভ্রমণ করুন, 3D জীবন্ত সাংস্কৃতিক ঐতিহ্যের সাথে যুক্ত হন এবং প্রাচীন ডিজিটাল পাণ্ডুলিপির পাতা উল্টান।",
    ta: "இந்தியாவின் புனித புவியியலில் ஒரு சுற்றுப்பாதை பயணத்தைத் தொடங்குங்கள். 360° AR/VR இல் காலத்தால் அழியாத நினைவுச்சின்னங்களை உலாவுங்கள், 3D பாரம்பரியங்களுடன் உரையாடுங்கள் மற்றும் பண்டைய கையெழுத்துப் பிரதிகளைப் புரட்டுங்கள்.",
    te: "భారతీయ పవిత్ర భూగోళం అంతటా కక్ష్యా ప్రయాణాన్ని ప్రారంభించండి. ఫోటోరియలిస్టిక్ 360° AR/VRలో స్మారక చిహ్నాలను దాటండి, 3D సజీవ సంప్రదాయాలతో సంభాషించండి మరియు ప్రాచీన మాన్యుస్క్రిప్ట్‌లను తిరగేయండి.",
    gu: "ભારતના પવિત્ર ભૂગોળની કક્ષીય યાત્રા શરૂ કરો. ફોટોરિઆલિસ્ટિક 360° AR/VR માં સ્મારકોની મુલાકાત લો, 3D જીવંત પરંપરાઓ સાથે ક્રિયાપ્રતિક્રિયા કરો અને પ્રાચીન ડિજિટલ હસ્તપ્રતોના પાના ફેરવો.",
    kn: "ಭಾರತದ ಪವಿತ್ರ ಭೂಗೋಳದ ಕಕ್ಷೀಯ ಪ್ರಯಾಣವನ್ನು ಪ್ರಾರಂಭಿಸಿ. ಫೋಟೊರಿಯಲಿಸ್ಟಿಕ್ 360° AR/VR ನಲ್ಲಿ ಕಾಲಾತೀತ ಸ್ಮಾರಕಗಳನ್ನು ವೀಕ್ಷಿಸಿ, 3D ಜೀವಂತ ಸಂಪ್ರದಾಯಗಳೊಂದಿಗೆ ಸಂವಹನ ನಡೆಸಿ ಮತ್ತು ಪ್ರಾಚೀನ ಡಿಜಿಟಲ್ ಹಸ್ತಪ್ರತಿಗಳನ್ನು ತಿರುವಿ.",
    ml: "ഭാരതത്തിന്റെ വിശുദ്ധ ഭൂമിശാസ്ത്രത്തിലൂടെ ഒരു ഭ്രമണപഥ യാത്ര ആരംഭിക്കുക. 360° AR/VR-ൽ സ്മാരകങ്ങൾ കാണുക, 3D സാംസ്കാരിക പാരമ്പര്യങ്ങളുമായി സംവദിക്കുക, പുരാതന ഡിജിറ്റൽ കൈയെഴുത്തുപ്രതികൾ വായിക്കുക.",
    pa: "ਭਾਰਤ ਦੇ ਪਵਿੱਤਰ ਭੂਗੋਲ ਦੀ ਯਾਤਰਾ 'ਤੇ ਨਿਕਲੋ। ਫੋਟੋਰੀਅਲਿਸਟਿਕ 360° AR/VR ਵਿੱਚ ਸਮਾਰਕਾਂ ਨੂੰ ਦੇਖੋ, 3D ਸੱਭਿਆਚਾਰਕ ਪਰੰਪਰਾਵਾਂ ਨਾਲ ਜੁੜੋ ਅਤੇ ਪੁਰਾਣੇ ਡਿਜੀਟਲ ਖਰੜਿਆਂ ਦੇ ਪੰਨੇ ਪਲਟੋ।",
    sa: "भारतस्य पवित्र-भूगोलस्य कक्षीय-यात्रां प्रारभन्ताम्। 360° AR/VR माध्यमेन कालजयी-स्मारकाणि पश्यन्तु, 3D परम्पराभिः सह संवदन्तु, प्राचीन-पाण्डुलिपीनां पत्राणि च परावर्तयन्तु।",
    ur: "ہندوستان کے مقدس جغرافیے کے مداری سفر کا آغاز کریں۔ فوٹوریلسٹک 360° AR/VR میں لازوال یادگاروں کا مشاہدہ کریں، 3D روایات کے ساتھ تعامل کریں اور قدیم مخطوطات کے صفحات پلٹیں۔",
    es: "Embárquese en un viaje orbital por la geografía sagrada de la India. Recorra monumentos atemporales en AR/VR fotorrealista de 360°, interactúe con tradiciones culturales vivas en 3D y pase las páginas de antiguos manuscritos digitales.",
    fr: "Embarquez pour un voyage orbital à travers la géographie sacrée de l'Inde. Parcourez des monuments intemporels en AR/VR 360° photoréaliste, interagissez avec des traditions culturelles vivantes en 3D et feuilletez d'anciens manuscrits numériques.",
    de: "Begeben Sie sich auf eine orbitale Reise durch die heilige Geografie Indiens. Durchqueren Sie zeitlose Monumente in fotorealistischem 360°-AR/VR, interagieren Sie mit lebendigen 3D-Kulturtraditionen und blättern Sie in alten digitalen Manuskripten.",
    ja: "インドの神聖な地理を巡る軌道旅行に出かけましょう。フォトリアリスティックな360° AR/VRで時代を超越した記念碑を巡り、3Dの生きた文化の伝統と対話し、古代のデジタル写本のページをめくります。"
  },
