  "Experience this living classical tradition through authentic performance showcase, musical rhythms, and cultural archives.": {
    hi: "प्रामाणिक कला प्रदर्शन, संगीतमय ताल और सांस्कृतिक अभिलेखों के माध्यम से इस जीवंत शास्त्रीय परंपरा का अनुभव करें।",
    mr: "अस्सल कला सादरीकरण, संगीतमय ताल आणि सांस्कृतिक दस्तऐवजांद्वारे या जिवंत परंपरेचा प्रत्यक्ष अनुभव घ्या.",
    bn: "খাঁটি পরিবেশনা, সঙ্গীত এবং সাংস্কৃতিক রেকর্ডের মাধ্যমে এই জীবন্ত ঐতিহ্যের অভিজ্ঞতা নিন।",
    ta: "நேரடி கலை நிகழ்ச்சி, இசை தாளங்கள் மற்றும் கலாச்சார ஆவணங்கள் மூலம் இந்த பாரம்பரியத்தை அனுபவியுங்கள்.",
    te: "ప్రామాణిక ప్రదర్శనలు, సంగీత లయలు మరియు ఆర్కైవ్‌ల ద్వారా ఈ సంప్రదాయాన్ని అనుభవించండి.",
    gu: "અધિકૃત કલા પ્રદર્શન, સંગીતના તાલ અને સાંસ્કૃતિક રેકોર્ડ દ્વારા આ જીવંત પરંપરાનો અનુભવ કરો.",
    kn: "ಅಧಿಕೃತ ಪ್ರದರ್ಶನಗಳು ಮತ್ತು ಸಂಗೀತ ಲಯಗಳ ಮೂಲಕ ಈ ಜೀವಂತ ಪರಂಪರೆಯನ್ನು ಅನುಭವಿಸಿ.",
    ml: "ആധികാരിക പ്രകടനങ്ങളിലൂടെയും സംഗീത താളങ്ങളിലൂടെയും ഈ പാരമ്പര്യം അനുഭവിച്ചറിയൂ.",
    pa: "ਪ੍ਰਮਾਣਿਕ ਪੇਸ਼ਕਾਰੀਆਂ ਅਤੇ ਸੰਗੀਤ ਰਾਹੀਂ ਇਸ ਜੀਵੰਤ ਪਰੰਪਰਾ ਦਾ ਅਨੁਭਵ ਕਰੋ।",
    sa: "प्रामाणिक-कला-प्रदर्शनैः, सङ्गीत-तालैः, सांस्कृतिक-अभिलेकैश्च अस्याः सजीव-परम्परायाः अनुभवं कुर्वन्तु।",
    ur: "مستند فنکارانہ کارکردگی اور موسیقی کی تال کے ذریعے اس زندہ روایت کا تجربہ کریں۔",
    es: "Experimente esta tradición viva a través de muestras auténticas, ritmos musicales y archivos culturales.",
    fr: "Découvrez cette tradition vivante grâce à des performances authentiques, des rythmes musicaux et des archives.",
    de: "Erleben Sie diese lebendige Tradition durch authentische Vorführungen, musikalische Rhythmen und Kulturarchive.",
    ja: "本物の公演ショーケース、音楽のリズム、文化アーカイブを通じて、この生きた伝統を体験してください。",
  },
